type Formatter = (value: number) => string;

const currency: Formatter = (n) => `$${n.toFixed(2)}`;
const percent: Formatter = (n) => `${(n * 100).toFixed(1)}%`;

function print(fmt: Formatter, value: number) {
  console.log(fmt(value));
}

interface EventEmitter {
  (event: string, payload: unknown): void;
  listeners: number;
}

const emit: EventEmitter = Object.assign(
  (event: string, payload: unknown) => console.log(event, payload),
  { listeners: 0 }
);

type Logger = (msg: string) => void;

const log: Logger = (msg) => {
  console.log(msg);
  return undefined; // OK — void allows implicit undefined
};

const bad: Logger = (msg) => msg; // Error: string not assignable to void

function run(fn: Function) {
  return fn('anything'); // no param checking
}

run((x: number) => x * 2); // compiles — may break at runtime
